'use client'

import { useTransition } from 'react'
import { toggleNotificationPreference } from '../actions/notifications'

interface NotificationToggleProps {
  userId: string
  currentPath: string
  initialEnabled?: boolean
}

export default function NotificationToggle({
  userId,
  currentPath,
  initialEnabled = false
}: NotificationToggleProps) {
  const [isPending, startTransition] = useTransition()

  const handleToggle = () => {
    startTransition(async () => {
      const result = await toggleNotificationPreference(userId, currentPath)

      if (!result.success) {
        console.error('Failed to toggle notification:', result.error)
        // You could add toast notification or error handling here
      }
    })
  }

  return (
    <div className="flex items-center gap-3">
      <label htmlFor="notification-toggle" className="text-sm font-medium">
        Notifications
      </label>
      <button
        id="notification-toggle"
        onClick={handleToggle}
        disabled={isPending}
        className={`
          relative inline-flex h-6 w-11 items-center rounded-full
          transition-colors focus:outline-none focus:ring-2 focus:ring-offset-2
          ${isPending ? 'opacity-50 cursor-not-allowed' : 'cursor-pointer'}
          ${initialEnabled ? 'bg-blue-600' : 'bg-gray-200'}
        `}
        role="switch"
        aria-checked={initialEnabled}
      >
        <span
          className={`
            inline-block h-4 w-4 transform rounded-full bg-white transition-transform
            ${initialEnabled ? 'translate-x-6' : 'translate-x-1'}
          `}
        />
      </button>
      {isPending && (
        <span className="text-xs text-gray-500">Updating...</span>
      )}
    </div>
  )
}

