import NotificationToggle from '../components/NotificationToggle'

// This would typically fetch from your database
async function getUserSettings(userId: string) {
  // Example: const user = await db.user.findUnique({ where: { id: userId } })
  // return { notificationsEnabled: user.notificationsEnabled }
  return { notificationsEnabled: true }
}

export default async function SettingsPage() {
  // In a real app, get the userId from your auth session
  const userId = 'user-123'
  const settings = await getUserSettings(userId)

  return (
    <div className="max-w-2xl mx-auto p-6">
      <h1 className="text-2xl font-bold mb-6">Settings</h1>

      <div className="bg-white rounded-lg shadow p-6">
        <h2 className="text-lg font-semibold mb-4">Preferences</h2>

        <NotificationToggle
          userId={userId}
          currentPath="/settings"
          initialEnabled={settings.notificationsEnabled}
        />

        <p className="mt-2 text-sm text-gray-600">
          Current status: {settings.notificationsEnabled ? 'Enabled' : 'Disabled'}
        </p>
      </div>
    </div>
  )
}

